import XCTest
@testable import Duomulator

/// Nintendo DS support: melonDS behind the same EmulatorCore API. Uses dstest.nds, a public
/// domain ROM generated by Tests/Fixtures/make-ds-test-rom.py that fills the top screen with
/// a color gradient.
final class DSCoreTests: XCTestCase {
    private var core: EmulatorCore!
    private var createdROMs: [URL] = []

    override func setUp() {
        super.setUp()
        core = EmulatorCore()
    }

    override func tearDown() {
        core.unload()
        for rom in createdROMs {
            try? FileManager.default.removeItem(at: GamePaths.sram(for: rom))
            for slot in 0...9 { try? FileManager.default.removeItem(at: GamePaths.state(for: rom, slot: slot)) }
            try? FileManager.default.removeItem(at: rom)
        }
        createdROMs = []
        core = nil
        super.tearDown()
    }

    private func makeROM(_ name: String, _ ext: String) throws -> URL {
        let source = try XCTUnwrap(Bundle(for: DSCoreTests.self).url(forResource: name, withExtension: ext),
                                   "\(name).\(ext) missing from the test bundle")
        let url = FileManager.default.temporaryDirectory
            .appending(path: "duotest-\(UUID().uuidString).\(ext)")
        try FileManager.default.copyItem(at: source, to: url)
        createdROMs.append(url)
        return url
    }

    private func latestFrame() -> EmulatorCore.TestFrame {
        core.frameBuffer.withLatestFrame { frame, base in
            let pixels = Array(UnsafeBufferPointer(start: base.assumingMemoryBound(to: UInt16.self),
                                                   count: frame.width * frame.height))
            return EmulatorCore.TestFrame(width: frame.width, height: frame.height,
                                          sequence: frame.sequence, pixels: pixels)
        }
    }

    func testSystemAndPaths() {
        let rom = URL(filePath: "/tmp/Mario Kart DS.nds")
        XCTAssertEqual(GameSystem.of(rom: rom), .nds)
        XCTAssertTrue(GameSystem.nds.isDualScreen)
        XCTAssertEqual(GamePaths.sram(for: rom), GamePaths.saves.appending(path: "DS/Mario Kart DS.sav"))
        XCTAssertEqual(GamePaths.state(for: rom, slot: 1), GamePaths.states.appending(path: "DS/Mario Kart DS.s1"))
    }

    func testBootsAndRendersBothScreens() throws {
        try core.load(rom: try makeROM("dstest", "nds"))
        XCTAssertEqual(core.system, .nds)
        XCTAssertEqual(core.frameRate, 59.8, accuracy: 0.3)
        XCTAssertGreaterThan(core.sampleRate, 8000)

        let start = Date()
        core.runFrames(120)
        let fps = 120 / Date().timeIntervalSince(start)
        print("DS interpreter speed: \(Int(fps)) fps (Debug build)")

        let frame = latestFrame()
        XCTAssertEqual(frame.width, 256)
        XCTAssertEqual(frame.height, 384, "top and bottom screens stacked")
        let top = frame.pixels[0..<(256 * 192)]
        XCTAssertGreaterThan(Set(top).count, 100, "top screen should show the gradient")
    }

    func testSaveStateRoundTrip() throws {
        let rom = try makeROM("dstest", "nds")
        try core.load(rom: rom)
        core.runFrames(30)
        try core.saveState(slot: 1)
        XCTAssertTrue(core.hasState(slot: 1))
        core.runFrames(30)
        try core.loadState(slot: 1)
        core.runFrames(5)
        XCTAssertEqual(latestFrame().height, 384)
    }

    func testSwitchingBetweenAllThreeSystems() throws {
        let snes = try makeROM("cputest-basic", "sfc")
        let nes = try makeROM("240pee", "nes")
        let ds = try makeROM("dstest", "nds")

        for (rom, system, height) in [(ds, GameSystem.nds, 384), (snes, .snes, 224), (nes, .nes, -1),
                                      (ds, .nds, 384), (snes, .snes, 224)] {
            try core.load(rom: rom)
            XCTAssertEqual(core.system, system)
            core.runFrames(90)
            let frame = latestFrame()
            XCTAssertEqual(frame.width, 256, "\(system)")
            if height > 0 { XCTAssertEqual(frame.height, height, "\(system)") }
            XCTAssertGreaterThan(Set(frame.pixels).count, 1, "\(system) frame is a single flat color")
        }
    }
}
